use std::{env, fs};

use zed::settings::LspSettings;
use zed_extension_api::{self as zed, serde_json};

const LANGUAGE_SERVER_ID: &str = "bdd-widget-test";
const SERVER_PATH: &str = "server.cjs";
const SERVER_SOURCE: &str = include_str!("../server/server.cjs");

/// Writes the embedded language server next to the extension assets
/// and returns its path. The server is a zero-dependency Node bundle
/// (see server/server.cjs, generated by `npm run build:zed`), so no npm
/// install is required.
fn write_server() -> zed::Result<String> {
    fs::write(SERVER_PATH, SERVER_SOURCE).map_err(|e| e.to_string())?;
    Ok(SERVER_PATH.to_string())
}

struct BddWidgetTestExtension;

impl zed::Extension for BddWidgetTestExtension {
    fn new() -> Self {
        Self
    }

    fn language_server_command(
        &mut self,
        _language_server_id: &zed::LanguageServerId,
        worktree: &zed::Worktree,
    ) -> zed::Result<zed::Command> {
        let lsp_settings = LspSettings::for_worktree(LANGUAGE_SERVER_ID, worktree).ok();

        // 1. Binary explicitly configured in settings
        //    (`lsp.bdd-widget-test.binary.path`).
        if let Some(binary) = lsp_settings.as_ref().and_then(|s| s.binary.as_ref()) {
            if let Some(path) = binary.path.clone() {
                return Ok(zed::Command {
                    command: path,
                    args: binary
                        .arguments
                        .clone()
                        .unwrap_or_else(|| vec!["--stdio".into()]),
                    env: Default::default(),
                });
            }
        }

        // 2. Run the embedded server with Zed's bundled Node.
        let script_path = write_server()?;
        Ok(zed::Command {
            command: zed::node_binary_path()?,
            args: vec![
                env::current_dir()
                    .unwrap()
                    .join(&script_path)
                    .to_string_lossy()
                    .to_string(),
                "--stdio".into(),
            ],
            env: Default::default(),
        })
    }

    fn language_server_workspace_configuration(
        &mut self,
        _language_server_id: &zed::LanguageServerId,
        worktree: &zed::Worktree,
    ) -> zed::Result<Option<zed::serde_json::Value>> {
        // The server requests the `bddWidgetTestHelper` configuration section,
        // so the value is that section's content.
        let settings = LspSettings::for_worktree(LANGUAGE_SERVER_ID, worktree)
            .ok()
            .and_then(|lsp_settings| lsp_settings.settings.clone())
            .unwrap_or_else(|| serde_json::json!({}));
        Ok(Some(settings))
    }
}

zed::register_extension!(BddWidgetTestExtension);
